using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using System.Collections.Generic;using System.Linq;
public static class BuildOffroadCourse {
 const string Dir="Assets/Environments/OffroadCourse";
 static Transform root;static Material dirt,gravel,shoulder,wood,white;static List<MeshFilter> roads=new List<MeshFilter>();
 static Material Mat(string name,Color color){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Smoothness",.03f);AssetDatabase.CreateAsset(m,Dir+"/"+name+".mat");return m;}
 public static Vector3 Loop(float d){float arc=Mathf.PI*30f;d=Mathf.Repeat(d,160+2*arc);if(d<80){float x=155+d;float h=1.8f*Mathf.Pow(Mathf.Sin(d/80*Mathf.PI),4);return new Vector3(x,.04f+h,-30);}d-=80;if(d<arc){float a=-Mathf.PI/2+d/30;return new Vector3(235+30*Mathf.Cos(a),.04f,30*Mathf.Sin(a));}d-=arc;if(d<80){float h=1.4f*Mathf.Pow(Mathf.Sin(d/80*Mathf.PI),4);return new Vector3(235-d,.04f+h,30);}d-=80;float b=Mathf.PI/2+d/30;return new Vector3(155+30*Mathf.Cos(b),.04f,30*Mathf.Sin(b));}
 static GameObject Ribbon(string name,List<Vector3> points,float width,Material material,float grip,bool collision=true){var v=new Vector3[points.Count*2];var uv=new Vector2[v.Length];var t=new int[(points.Count-1)*6];float length=0;for(int i=0;i<points.Count;i++){var tangent=points[Mathf.Min(i+1,points.Count-1)]-points[Mathf.Max(i-1,0)];if(i==0&&(points[0]-points[points.Count-1]).sqrMagnitude<.001f)tangent=points[1]-points[points.Count-2];if(i==points.Count-1&&(points[0]-points[i]).sqrMagnitude<.001f)tangent=points[1]-points[i-1];var side=Vector3.Cross(Vector3.up,tangent).normalized*width*.5f;v[i*2]=points[i]+side;v[i*2+1]=points[i]-side;if(i>0)length+=Vector3.Distance(points[i],points[i-1]);uv[i*2]=new Vector2(0,length/4);uv[i*2+1]=new Vector2(width/4,length/4);if(i<points.Count-1){int j=i*2,k=i*6;t[k]=j;t[k+1]=j+1;t[k+2]=j+2;t[k+3]=j+1;t[k+4]=j+3;t[k+5]=j+2;}}
 var mesh=new Mesh{name=name};mesh.vertices=v;mesh.uv=uv;mesh.triangles=t;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Dir+"/"+name+".asset");var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(root,false);g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<MeshRenderer>().sharedMaterial=material;if(collision){g.AddComponent<MeshCollider>().sharedMesh=mesh;var surface=g.AddComponent<TestDriveSurface>();var so=new SerializedObject(surface);so.FindProperty("gripMultiplier").floatValue=grip;so.ApplyModifiedPropertiesWithoutUndo();roads.Add(g.GetComponent<MeshFilter>());}return g;}
 static GameObject Box(string name,Vector3 pos,Vector3 size,Material m,bool collision=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(root);g.transform.position=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;if(!collision)Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Sign(string text,Vector3 pos,float yaw){Box("Sign post",pos+Vector3.up*1.2f,new Vector3(.18f,2.4f,.18f),wood);var g=new GameObject(text,typeof(TextMesh));g.transform.SetParent(root);g.transform.SetPositionAndRotation(pos+Vector3.up*2.7f,Quaternion.Euler(0,yaw,0));var tm=g.GetComponent<TextMesh>();tm.text=text;tm.fontSize=48;tm.characterSize=.11f;tm.anchor=TextAnchor.MiddleCenter;tm.color=Color.white;}
 public static string Main(){if(EditorApplication.isPlaying)throw new System.Exception("Stop Play");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/TestTrackScene.unity"||scene.isDirty)throw new System.Exception("Clean test track required");if(GameObject.Find("Offroad Course"))throw new System.Exception("Course already exists");if(!AssetDatabase.IsValidFolder(Dir))AssetDatabase.CreateFolder("Assets/Environments","OffroadCourse");root=new GameObject("Offroad Course").transform;dirt=Mat("Packed Dirt",new Color(.43f,.28f,.15f));gravel=Mat("Loose Gravel",new Color(.53f,.49f,.4f));shoulder=Mat("Dusty Shoulder",new Color(.56f,.42f,.24f));wood=Mat("Timber",new Color(.2f,.13f,.07f));white=Mat("Trail Marker",new Color(.93f,.68f,.18f));var grass=AssetDatabase.LoadAssetAtPath<Material>("Assets/Environments/TestTrack/Track_Grass.mat");Box("Offroad ground",new Vector3(210,-.3f,0),new Vector3(240,.5f,160),grass,true);
 // Clear only scenery that overlaps the new driving area or connector.
 foreach(var r in Object.FindObjectsByType<Renderer>()){if(r.transform.IsChildOf(root))continue;var p=r.bounds.center;if(r.name=="Distant grassy hill"&&p.x>110){var hillPosition=r.transform.position;hillPosition.z=p.z>=0?140:-140;r.transform.position=hillPosition;continue;}if(r.name.StartsWith("Pine")&&p.x>90&&Mathf.Abs(p.z)<18){Object.DestroyImmediate(r.gameObject);continue;}if((r.name.StartsWith("Barrier ")||r.name.StartsWith("Curb "))&&p.x>77&&Mathf.Abs(p.z)<10.5f)Object.DestroyImmediate(r.gameObject);}
 var oval=GameObject.Find("Asphalt — 12m wide").GetComponent<MeshFilter>();roads.Add(oval);
 float arc=Mathf.PI*30;var full=new List<Vector3>();for(int i=0;i<=400;i++)full.Add(Loop(i/400f*(160+2*arc)));Ribbon("Dirt shoulders",full.Select(p=>p-Vector3.up*.025f).ToList(),18,shoulder,1,false);
 float[] starts={0,80,80+arc,160+arc};float[] lengths={80,arc,80,arc};for(int part=0;part<4;part++){var pts=new List<Vector3>();for(int i=0;i<=100;i++)pts.Add(Loop(starts[part]+lengths[part]*i/100));Ribbon(part%2==0?"Dirt Hill "+(part/2+1):"Gravel Corner "+(part/2+1),pts,14,part%2==0?dirt:gravel,part%2==0?.82f:.67f);}
 var connector=new List<Vector3>();for(int i=0;i<=48;i++)connector.Add(new Vector3(Mathf.Lerp(73,130,i/48f),Mathf.Lerp(.02f,.04f,i/48f),0));Ribbon("Dirt access road",connector,14,dirt,.82f);
 // Branch joins both ends of the northern straight with tangent-continuous bends.
 var branch=new List<Vector3>();for(int i=0;i<=160;i++){float u=i/160f;float bulge=Mathf.Pow(Mathf.Sin(Mathf.PI*u),2);float h=bulge*(1.2f+.55f*Mathf.Sin(u*6*Mathf.PI));branch.Add(new Vector3(235-80*u,.04f+h,30+27*bulge));}Ribbon("Truck ridge branch",branch,10,gravel,.72f);Ribbon("Branch shoulders",branch.Select(p=>p-Vector3.up*.025f).ToList(),13,shoulder,1,false);
 // Rounded, low rocks stay outside the main loop and mark the branch edges.
 Random.InitState(731);for(int i=0;i<56;i++){float d=i/56f*(160+2*arc);var p=Loop(d);var tangent=Loop(d+.1f)-p;var side=Vector3.Cross(Vector3.up,tangent).normalized;foreach(float direction in new[]{-1f,1f}){var mark=p+side*direction*8.7f;Box("Trail edge marker",mark+Vector3.up*.35f,new Vector3(.18f,.7f,.18f),white);}}
 for(int i=0;i<16;i++){float u=.16f+(i+.5f)/16*.68f;int index=Mathf.RoundToInt(u*160);var p=branch[index];var tangent=branch[Mathf.Min(index+1,160)]-branch[Mathf.Max(index-1,0)];var side=Vector3.Cross(Vector3.up,tangent).normalized;var g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name="Branch boundary boulder";g.transform.SetParent(root);g.transform.position=p+side*7.5f;g.transform.localScale=new Vector3(1.2f,.8f,1.3f);g.GetComponent<Renderer>().sharedMaterial=gravel;}
 Sign("DIRT LOOP\n14m wide | gravel turns",new Vector3(92,0,10),90);Sign("TRUCK RIDGE\nOptional rough route",new Vector3(230,0,42),180);Sign("MAIN LOOP",new Vector3(219,0,20),180);
 var combines=roads.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=f.transform.localToWorldMatrix}).ToArray();var mapMesh=new Mesh{name="Combined course map"};mapMesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mapMesh.CombineMeshes(combines);AssetDatabase.CreateAsset(mapMesh,Dir+"/CourseMap.asset");var map=Object.FindAnyObjectByType<TestDriveMinimap>();var ms=new SerializedObject(map);ms.FindProperty("roadMesh").objectReferenceValue=mapMesh;ms.FindProperty("roadTransform").objectReferenceValue=root;ms.ApplyModifiedPropertiesWithoutUndo();map.SetVerticesDirty();
 FinishOffroad.Main();OffroadSurfaceTextures.Main();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Selection.activeGameObject=root.gameObject;if(SceneView.lastActiveSceneView)SceneView.lastActiveSceneView.LookAt(new Vector3(155,0,0),Quaternion.Euler(60,0,0),185);return "Built 348m dirt/gravel loop, 14m main width, hills 1.8m and 1.4m, 10m optional truck ridge, east access, combined minimap.";}
}

public static class FinishOffroad {
 public static string Main(){var root=GameObject.Find("Offroad Course").transform;foreach(string name in new[]{"Dirt Hill 1","Dirt Hill 2","Truck ridge branch"}){var road=root.Find(name).GetComponent<MeshFilter>().sharedMesh;var verts=road.vertices;var pts=new List<Vector3>();for(int i=0;i<verts.Length;i+=2)pts.Add((verts[i]+verts[i+1])*.5f);Bank(root,name+" earth banks",pts,name.StartsWith("Truck")?6.5f:9f,name.StartsWith("Truck")?15f:20f);}
 EditorSceneManager.SaveScene(root.gameObject.scene);return "Added smooth soil banks around both hills and truck ridge.";}
 static void Bank(Transform root,string name,List<Vector3> pts,float inner,float outer){int across=16;var v=new Vector3[pts.Count*(across+1)];var tri=new List<int>();for(int i=0;i<pts.Count;i++){var tangent=pts[Mathf.Min(i+1,pts.Count-1)]-pts[Mathf.Max(i-1,0)];var side=Vector3.Cross(Vector3.up,tangent).normalized;for(int j=0;j<=across;j++){float offset=Mathf.Lerp(-outer,outer,j/(float)across);float blend=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(inner,outer,Mathf.Abs(offset)));var p=pts[i]+side*offset;p.y=-.045f+(pts[i].y-.04f)*blend;int k=i*(across+1)+j;v[k]=p;if(i<pts.Count-1&&j<across){tri.Add(k);tri.Add(k+1);tri.Add(k+across+1);tri.Add(k+1);tri.Add(k+across+2);tri.Add(k+across+1);}}}var mesh=new Mesh{name=name};mesh.vertices=v;for(int k=0;k<tri.Count;k+=3){int temp=tri[k+1];tri[k+1]=tri[k+2];tri[k+2]=temp;}mesh.triangles=tri.ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/Environments/OffroadCourse/"+name+".asset");var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer),typeof(MeshCollider),typeof(TestDriveSurface));go.transform.SetParent(root,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshCollider>().sharedMesh=mesh;go.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Environments/OffroadCourse/Dusty Shoulder.mat");}
}

public static class OffroadSurfaceTextures {
 public static string Main(){Make("Packed Dirt",false);Make("Loose Gravel",true);AssetDatabase.SaveAssets();return "Added tiled soil grain and gravel detail.";}
 static void Make(string name,bool gravel){const int n=256;var tex=new Texture2D(n,n,TextureFormat.RGB24,true){name=name+" Detail",wrapMode=TextureWrapMode.Repeat,filterMode=FilterMode.Bilinear};var pixels=new Color[n*n];var rand=new System.Random(gravel?175:83);for(int y=0;y<n;y++)for(int x=0;x<n;x++){float noise=Mathf.PerlinNoise(x/32f,y/32f);float value=.78f+noise*.27f+(float)rand.NextDouble()*(gravel?.23f:.1f);pixels[y*n+x]=new Color(value,value,value);}
 if(gravel)for(int i=0;i<2400;i++){int x=rand.Next(n),y=rand.Next(n);float value=.52f+(float)rand.NextDouble()*.65f;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){if(dx*dx+dy*dy>1)continue;pixels[((y+dy+n)%n)*n+(x+dx+n)%n]=new Color(value,value,value);}}
 tex.SetPixels(pixels);tex.Apply(true,false);AssetDatabase.CreateAsset(tex,"Assets/Environments/OffroadCourse/"+name+" Detail.asset");var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Environments/OffroadCourse/"+name+".mat");mat.SetTexture("_BaseMap",tex);EditorUtility.SetDirty(mat);}
}
